const japanPrefecturesGzipBase64 = "";
const japanPrefecturesBytes = Uint8Array.from(atob(japanPrefecturesGzipBase64), (character) => character.charCodeAt(0));
window.JAPAN_PREFECTURES_READY = new Response(
  new Blob([japanPrefecturesBytes]).stream().pipeThrough(new DecompressionStream("gzip"))
).json().then((geojson) => {
  window.JAPAN_PREFECTURES = geojson;
  return geojson;
});
